<script setup lang="ts">import { useDeliveryStore } from '../store'; const store = useDeliveryStore()</script>
<template><section class="panel"><div class="panel-title"><div><span class="eyebrow">Skills matching across borders</span><h2>Quantum skills matching board</h2></div><span>{{ store.loading ? 'Loading…' : 'Updated now' }}</span></div><label class="search">Find a skills plan<input v-model="store.query" aria-label="Find a skills plan" placeholder="Search by occupation, skill, owner or status"></label><p v-if="store.error" role="alert">{{ store.error }}</p><div class="release header-row"><span>Skills plan</span><span>Owner</span><span>Progress</span><span>Priority</span><span>Status</span><span>Action</span></div><div v-for="offer in store.visibleOffers" :key="offer.id" class="release"><b>{{ offer.title }}</b><span>{{ offer.owner }}</span><div class="mini-bar"><i :style="{ width: offer.status === 'Approved' ? '100%' : offer.status === 'Review' ? '65%' : '30%' }" /></div><span :class="['risk', offer.priority === 'High' ? 'medium' : '']">{{ offer.priority }}</span><span>{{ offer.status }}</span><button v-if="offer.status !== 'Approved'" @click="store.advanceOffer(offer)">Move forward</button></div><p v-if="!store.loading && store.visibleOffers.length === 0">No skills plans match this search.</p></section></template>
